#!/usr/bin/env python3
"""Render one accepted Germinal Expression Card as a self-contained HTML prototype.

The renderer is public infrastructure. Restricted Card data is supplied at build time and
is embedded only in the resulting private draft-release artifact.
"""
import argparse, hashlib, html, json, pathlib, sys
VERSION = "germinal-full-expression-card-renderer-v1"

def canon(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode() + b"\n"

def safe_json(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")

CSS = r'''
:root{--ink:#14213d;--muted:#5f687b;--paper:#fffdf8;--wash:#f4f0e7;--line:#dcd6c8;--navy:#183153;--verm:#c84630;--teal:#167c73;--gold:#b9770e;--violet:#7656a8;--lex-bg:#e7f1ff;--lex-br:#2f6fb3;--gram-bg:#fff3cd;--gram-br:#a66b00;--aux-bg:#f1eafe;--aux-br:#7656a8;--punct-bg:#f0f1f3;--punct-br:#747b87;--shadow:0 18px 55px rgba(24,49,83,.12);--radius:22px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:linear-gradient(180deg,#ede8dd 0,#f7f4ed 260px,var(--wash) 100%);color:var(--ink);font:16px/1.58 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button{font:inherit}a{color:inherit}.skip{position:absolute;left:-9999px}.skip:focus{left:16px;top:12px;z-index:99;background:#fff;padding:10px 14px;border-radius:10px}.topbar{position:sticky;top:0;z-index:30;background:rgba(255,253,248,.9);backdrop-filter:blur(16px);border-bottom:1px solid rgba(220,214,200,.9)}.topbar-inner{max-width:1180px;margin:auto;padding:12px 22px;display:flex;align-items:center;gap:14px}.brand{font-weight:900;letter-spacing:.08em;color:var(--navy)}.crumb{color:var(--muted);font-size:.88rem}.spacer{flex:1}.status{display:inline-flex;align-items:center;gap:7px;border:1px solid #b9d9d3;background:#e9f8f5;color:#0c5d56;padding:5px 10px;border-radius:999px;font-size:.78rem;font-weight:800}.status:before{content:"✓";font-weight:900}.shell{max-width:1180px;margin:32px auto 80px;padding:0 22px;display:grid;grid-template-columns:220px minmax(0,1fr);gap:26px}.rail{position:sticky;top:78px;align-self:start}.rail-card{background:rgba(255,253,248,.82);border:1px solid var(--line);border-radius:18px;padding:12px;box-shadow:0 9px 28px rgba(24,49,83,.06)}.rail a{display:block;text-decoration:none;padding:9px 11px;margin:2px 0;border-radius:10px;color:#4d5669;font-size:.9rem}.rail a:hover,.rail a:focus{background:#ebe6dc;color:var(--navy);outline:none}.main{min-width:0}.hero{position:relative;overflow:hidden;background:var(--paper);border:1px solid var(--line);border-radius:30px;padding:34px;box-shadow:var(--shadow)}.hero:after{content:"";position:absolute;width:300px;height:300px;border-radius:50%;right:-135px;top:-130px;background:radial-gradient(circle,#f4d7c8 0,#f7e8dc 45%,transparent 70%)}.eyebrow{display:flex;flex-wrap:wrap;align-items:center;gap:8px;color:var(--verm);font-weight:850;text-transform:uppercase;letter-spacing:.1em;font-size:.75rem}.hero-jp{position:relative;z-index:1;font-family:"Hiragino Sans","Yu Gothic",Meiryo,sans-serif;font-size:clamp(4.2rem,12vw,8.4rem);line-height:1;margin:20px 0 8px;letter-spacing:-.04em}.reading{color:var(--muted);font-size:1rem}.hero-meaning{max-width:720px;font:700 clamp(1.35rem,2.5vw,2rem)/1.3 Georgia,serif;margin:15px 0;color:#253858}.chips{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.chip{border:1px solid var(--line);background:#f8f5ee;padding:6px 10px;border-radius:999px;font-size:.8rem;font-weight:800;color:#50596b}.chip.warn{border-color:#edc4b8;background:#fff1ed;color:#8c3323}.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}.action{border:1px solid var(--navy);background:var(--navy);color:#fff;padding:10px 14px;border-radius:12px;font-weight:800;cursor:pointer}.action.secondary{background:#fff;color:var(--navy)}.action[aria-pressed=true]{background:var(--teal);border-color:var(--teal);color:#fff}.study-state{min-height:24px;margin-top:9px;color:var(--muted);font-size:.86rem}.difficulty{display:flex;align-items:center;gap:8px;margin-top:16px;color:var(--muted);font-size:.86rem}.dots{display:flex;gap:5px}.dot{width:10px;height:10px;border-radius:50%;border:1px solid #a8acb4;background:#fff}.dot.on{background:var(--verm);border-color:var(--verm)}.section{margin-top:26px;background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:26px;box-shadow:0 8px 28px rgba(24,49,83,.055)}.section h2{margin:0 0 4px;font:800 1.55rem/1.25 Georgia,serif}.section-lead{margin:0 0 20px;color:var(--muted)}.grid-2,.grid-3{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.panel{border:1px solid var(--line);border-radius:16px;padding:17px;background:#fffefa}.panel h3{font-size:.92rem;text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px;color:var(--verm)}ul.clean{margin:0;padding-left:20px}.clean li+li{margin-top:8px}.line-card{border:1px solid var(--line);background:#fff;border-radius:18px;padding:17px;margin-top:12px;scroll-margin-top:96px}.line-card.compact{padding:14px}.line-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.line-id{font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:850}.jp{font:700 clamp(1.45rem,4vw,2.25rem)/1.35 "Hiragino Sans","Yu Gothic",Meiryo,sans-serif;letter-spacing:.015em}.compact .jp{font-size:1.45rem}.line-reading{color:var(--muted);font-size:.86rem;margin-top:2px}.line-meaning{font-weight:700;color:#2d405f;margin-top:5px}.segments{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.seg{position:relative;display:inline-flex;align-items:center;gap:7px;border:1.5px solid var(--lex-br);background:var(--lex-bg);color:#173b64;border-radius:11px;padding:7px 10px;cursor:pointer;min-height:42px}.seg:hover,.seg:focus-visible{transform:translateY(-1px);box-shadow:0 5px 14px rgba(24,49,83,.13);outline:3px solid rgba(47,111,179,.18);outline-offset:2px}.seg.kind-grammar{border-color:var(--gram-br);background:var(--gram-bg);color:#6e4700}.seg.kind-aux{border-color:var(--aux-br);background:var(--aux-bg);color:#54377c}.seg.kind-punct{border-color:var(--punct-br);background:var(--punct-bg);color:#4f5662}.seg-surface{font:800 1.05rem "Hiragino Sans","Yu Gothic",Meiryo,sans-serif}.seg-type{font-size:.58rem;letter-spacing:.06em;font-weight:900;opacity:.85}.segment-detail{margin-top:12px;border-left:4px solid var(--teal);background:#edf8f6;border-radius:0 12px 12px 0;padding:12px 14px;min-height:76px}.segment-detail strong{font-family:"Hiragino Sans","Yu Gothic",Meiryo,sans-serif}.meta{color:var(--muted);font-size:.83rem}.all-analysis{margin-top:12px;border-top:1px dashed var(--line);padding-top:10px}.all-analysis summary{cursor:pointer;font-weight:850;color:var(--navy)}.analysis-list{display:grid;gap:8px;margin-top:10px}.analysis-row{display:grid;grid-template-columns:minmax(70px,130px) 1fr;gap:12px;padding:10px;border:1px solid var(--line);border-radius:12px}.analysis-token{font-weight:900;font-family:"Hiragino Sans","Yu Gothic",Meiryo,sans-serif}.context{color:var(--muted);font-size:.88rem;margin-bottom:7px}.dialogue{display:grid;gap:14px}.turn{display:grid;grid-template-columns:38px 1fr;gap:10px}.avatar{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:var(--navy);color:#fff;font-weight:900}.turn:nth-child(even) .avatar{background:var(--verm)}.relationship{border-left:4px solid var(--gold)}.evidence{border-left:4px solid var(--teal)}.empty-note{background:#f7f4ee;border:1px dashed #b9b2a4;padding:13px;border-radius:12px;color:#5b6270}.library-tags{display:flex;flex-wrap:wrap;gap:7px}.library-tag{background:#eef1f6;border:1px solid #ccd3df;border-radius:999px;padding:5px 9px;font-size:.8rem}.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:.8rem;color:var(--muted);margin-top:15px}.key{display:inline-flex;align-items:center;gap:5px}.swatch{width:12px;height:12px;border-radius:4px;border:1px solid}.footer{margin-top:28px;padding:22px 4px;color:var(--muted);font-size:.82rem;text-align:center}.notice{background:#14213d;color:#fff;border-radius:14px;padding:14px 16px;margin-top:18px;font-size:.88rem}.notice strong{color:#ffd6bd}@media(max-width:850px){.shell{grid-template-columns:1fr}.rail{position:static}.rail-card{display:flex;overflow:auto;white-space:nowrap}.rail a{display:inline-block}.grid-3{grid-template-columns:1fr}.hero{padding:24px}.section{padding:20px}}@media(max-width:620px){.topbar-inner{padding:10px 14px}.crumb{display:none}.shell{padding:0 12px;margin-top:18px}.grid-2{grid-template-columns:1fr}.hero-jp{font-size:4.2rem}.analysis-row{grid-template-columns:1fr}.section,.hero{border-radius:18px}.hero-actions .action{flex:1}.status{font-size:.7rem}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.seg:hover{transform:none}}
'''

JS = r'''
const card=JSON.parse(document.getElementById('card-data').textContent);const acceptance=JSON.parse(document.getElementById('acceptance-data').textContent);const $=(q,e=document)=>e.querySelector(q);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kindMeta=k=>k==='particle-or-grammar'?['grammar','GRAM']:k==='auxiliary-or-inflection'?['aux','AUX']:k==='punctuation'?['punct','PUNCT']:['lexical','LEX'];
function segButtons(line,id){return `<div class="segments" role="group" aria-label="Tap a segment for its explanation">${line.segments.map((s,i)=>{const [cl,lab]=kindMeta(s.kind);return `<button class="seg kind-${cl}" data-line="${esc(id)}" data-seg="${i}" aria-label="${esc(s.surface)}: ${esc(lab)}"><span class="seg-surface" lang="ja">${esc(s.surface)}</span><span class="seg-type">${lab}</span></button>`}).join('')}</div>`}
function detail(s){const [,lab]=kindMeta(s.kind);return `<strong lang="ja">${esc(s.surface)}</strong> <span class="meta">${esc(s.reading||'—')} · ${lab}</span><br>${esc(s.contextualMeaning)}<div class="meta">Role: ${esc(s.grammaticalRole)}${s.lemma?` · Lemma: <span lang="ja">${esc(s.lemma)}</span>`:''}${s.inflection?` · Form: ${esc(s.inflection)}`:''}</div>`}
function analysisRows(line){return line.segments.map((s,i)=>`<div class="analysis-row"><div><span class="analysis-token" lang="ja">${esc(s.surface)}</span><div class="meta">${esc(s.reading||'—')} · ${kindMeta(s.kind)[1]}</div></div><div>${esc(s.contextualMeaning)}<div class="meta">${esc(s.grammaticalRole)}${s.lemma?` · lemma <span lang="ja">${esc(s.lemma)}</span>`:''}${s.inflection?` · ${esc(s.inflection)}`:''}</div></div></div>`).join('')}
function lineCard(id,compact=false,label='Analysed line'){const l=card.japaneseLines[id];return `<article class="line-card${compact?' compact':''}" id="line-${esc(id)}"><div class="line-head"><div><div class="line-id">${esc(label)} · ${esc(id)}</div><div class="jp" lang="ja">${esc(l.japanese)}</div><div class="line-reading" lang="ja">${esc(l.reading)}</div><div class="line-meaning">${esc(l.meaning)}</div></div><button class="action secondary listen-line" data-text="${esc(l.japanese)}" aria-label="Listen to this Japanese line">Listen</button></div>${segButtons(l,id)}<div class="segment-detail" aria-live="polite">${detail(l.segments[0])}</div><details class="all-analysis"><summary>Complete analysis · ${l.segments.length} segment${l.segments.length===1?'':'s'}</summary><div class="analysis-list">${analysisRows(l)}</div></details></article>`}
function list(xs){return `<ul class="clean">${(xs||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}
function render(){const p=card.japaneseLines[card.primaryLineId];$('#category').textContent=card.category.replaceAll('-',' ');$('#hero-jp').textContent=p.japanese;$('#hero-reading').textContent=p.reading;$('#hero-meaning').textContent=p.meaning;$('#difficulty-label').textContent=`Koto Difficulty ${card.kotoDifficulty}`;$('#difficulty-dots').innerHTML=[1,2,3,4,5].map(n=>`<span class="dot ${n<=card.kotoDifficulty?'on':''}" aria-hidden="true"></span>`).join('');$('#summary').textContent=card.usageSummary;$('#primary-analysis').innerHTML=lineCard(card.primaryLineId,false,'Primary expression');$('#intentions').innerHTML=list(card.intentions);$('#use-when').innerHTML=list(card.useWhen);$('#take-care').innerHTML=list(card.takeCare);$('#relationships').innerHTML=(card.relationships||[]).map(x=>`<div class="panel relationship"><h3>${esc(x.context)}</h3><p>${esc(x.guidance)}</p></div>`).join('');$('#forms').innerHTML=(card.forms||[]).map(x=>lineCard(x.lineId,true,`${x.kind} form · ${x.register}`)).join('');$('#responses').innerHTML=(card.responses||[]).map(x=>`<div><div class="context">${esc(x.context)}</div>${lineCard(x.lineId,true,'Natural response')}</div>`).join('');$('#follow-ups').innerHTML=(card.followUps||[]).map(x=>`<div><div class="context">${esc(x.context)}</div>${lineCard(x.lineId,true,'Useful follow-up')}</div>`).join('');$('#dialogue-meta').innerHTML=`<strong>Situation.</strong> ${esc(card.dialogue.situation)}<br><strong>Relationship.</strong> ${esc(card.dialogue.relationship)}<br><strong>Register.</strong> ${esc(card.dialogue.register)}`;$('#dialogue').innerHTML=card.dialogue.turns.map((t,i)=>`<div class="turn"><div class="avatar" aria-label="Speaker ${esc(t.speaker)}">${esc(t.speaker)}</div><div>${lineCard(t.lineId,true,`Dialogue turn ${i+1}`)}</div></div>`).join('');$('#all-lines').innerHTML=Object.keys(card.japaneseLines).map((id,i)=>lineCard(id,false,`Line ${i+1} of ${Object.keys(card.japaneseLines).length}`)).join('');$('#patterns').innerHTML=`<div class="empty-note"><strong>${esc(card.patterns.status)}</strong><br>${esc(card.patterns.reason)}</div>`;$('#distinctions').innerHTML=`<div class="empty-note"><strong>${esc(card.distinctions.status)}</strong><br>${esc(card.distinctions.reason)}</div>`;const lib=card.library;const groups=[['Intentions',lib.searchIntentions],['Meanings',lib.searchMeaning],['Usage',lib.searchUsage],['Japanese index',lib.searchJapanese],['Kana index',lib.searchKana]];$('#library').innerHTML=groups.map(([n,xs])=>`<div class="panel"><h3>${esc(n)}</h3><div class="library-tags">${(xs||[]).map(x=>`<span class="library-tag"${n.includes('Japanese')||n.includes('Kana')?' lang="ja"':''}>${esc(x)}</span>`).join('')}</div></div>`).join('');$('#evidence').innerHTML=`<div class="panel evidence"><h3>Evidence boundary</h3><p>Lexical and expression anchors support bounded factual claims. Situations, responses, follow-ups, and learner guidance remain editorial teaching content.</p><p class="meta">${card.sources.length} source anchors · ${esc(card.provenance.editorialStatus)}</p></div><div class="panel"><h3>Acceptance</h3><p>Accepted non-live after user preview and Zero review. The independent Crow linguistic gate was transparently waived; its mechanical matrices remain audit evidence.</p><p class="meta">${esc(acceptance.acceptanceId)}</p></div>`;$('#accepted-id').textContent=acceptance.acceptanceId}
function speak(text){if(!('speechSynthesis'in window)){alert('Japanese device speech is not available in this browser.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.rate=.88;speechSynthesis.speak(u)}
document.addEventListener('click',e=>{const seg=e.target.closest('.seg');if(seg){const line=card.japaneseLines[seg.dataset.line],s=line.segments[Number(seg.dataset.seg)],box=seg.closest('.line-card').querySelector('.segment-detail');box.innerHTML=detail(s);seg.closest('.segments').querySelectorAll('.seg').forEach(x=>x.setAttribute('aria-pressed',x===seg?'true':'false'));return}const lis=e.target.closest('.listen-line');if(lis){speak(lis.dataset.text);return}});
let study=null;function setStudy(next){study=study===next?null:next;$('#recognised').setAttribute('aria-pressed',study==='recognised');$('#review').setAttribute('aria-pressed',study==='review');$('#study-state').textContent=study==='recognised'?'Marked Recognised. Review is off.':study==='review'?'Added to Review. Recognised is off.':'No study state selected.'}$('#recognised').addEventListener('click',()=>setStudy('recognised'));$('#review').addEventListener('click',()=>setStudy('review'));$('#listen-primary').addEventListener('click',()=>speak(card.japaneseLines[card.primaryLineId].japanese));render();
'''

def render(card, acceptance):
    title = html.escape(card.get("japaneseLines", {}).get(card.get("primaryLineId"), {}).get("japanese", "Expression"))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{title} · Full Expression Card prototype</title><style>{CSS}</style></head><body><a class="skip" href="#content">Skip to Card</a><header class="topbar"><div class="topbar-inner"><div class="brand">KOTO</div><div class="crumb">Library / Full Expression Card</div><div class="spacer"></div><div class="status">Accepted · non-live</div></div></header><div class="shell"><nav class="rail" aria-label="Card sections"><div class="rail-card"><a href="#overview">Overview</a><a href="#usage">Usage</a><a href="#relationships-section">Relationships</a><a href="#responses-section">Responses</a><a href="#dialogue-section">Dialogue</a><a href="#analysis-section">Analysis</a><a href="#library-section">Library & evidence</a></div></nav><main class="main" id="content"><section class="hero" id="overview"><div class="eyebrow"><span id="category"></span><span>•</span><span>Full Expression Card</span></div><div class="hero-jp" id="hero-jp" lang="ja"></div><div class="reading" id="hero-reading" lang="ja"></div><div class="hero-meaning" id="hero-meaning"></div><div class="chips"><span class="chip">Casual reassurance</span><span class="chip">After a minor apology</span><span class="chip warn">Not affirmative permission</span></div><div class="difficulty"><strong id="difficulty-label"></strong><span class="dots" id="difficulty-dots"></span></div><div class="hero-actions"><button class="action" id="listen-primary">Listen in Japanese</button><button class="action secondary" id="recognised" aria-pressed="false">Mark Recognised</button><button class="action secondary" id="review" aria-pressed="false">Add to Review</button></div><div class="study-state" id="study-state" aria-live="polite">No study state selected.</div><div class="notice"><strong>Prototype.</strong> Speech uses the device voice only after you press Listen. Recognised and Review are mutually exclusive.</div></section><section class="section"><h2>At a glance</h2><p class="section-lead" id="summary"></p><div id="primary-analysis"></div><div class="legend"><span class="key"><span class="swatch" style="background:var(--lex-bg);border-color:var(--lex-br)"></span>LEX · lexical</span><span class="key"><span class="swatch" style="background:var(--gram-bg);border-color:var(--gram-br)"></span>GRAM · particle/grammar</span><span class="key"><span class="swatch" style="background:var(--aux-bg);border-color:var(--aux-br)"></span>AUX · auxiliary/inflection</span><span class="key"><span class="swatch" style="background:var(--punct-bg);border-color:var(--punct-br)"></span>PUNCT · punctuation</span></div></section><section class="section" id="usage"><h2>Meaning in use</h2><p class="section-lead">The social job of the expression, not just a gloss.</p><div class="grid-3"><div class="panel"><h3>Intentions</h3><div id="intentions"></div></div><div class="panel"><h3>Use when</h3><div id="use-when"></div></div><div class="panel"><h3>Take care</h3><div id="take-care"></div></div></div></section><section class="section" id="relationships-section"><h2>Relationships & forms</h2><p class="section-lead">Who can say it, and how the register changes the risk.</p><div class="grid-2" id="relationships"></div><div id="forms"></div></section><section class="section" id="responses-section"><h2>What comes next</h2><p class="section-lead">Natural responses and follow-ups, each fully analysed.</p><div class="grid-2"><div><h3>Responses</h3><div id="responses"></div></div><div><h3>Follow-ups</h3><div id="follow-ups"></div></div></div></section><section class="section" id="dialogue-section"><h2>Dialogue</h2><p class="section-lead" id="dialogue-meta"></p><div class="dialogue" id="dialogue"></div></section><section class="section" id="analysis-section"><h2>Every line, completely analysed</h2><p class="section-lead">Tap any coloured segment for its contextual explanation. Colour is reinforced by LEX, GRAM, AUX, and PUNCT labels.</p><div id="all-lines"></div></section><section class="section"><h2>Patterns & distinctions</h2><div class="grid-2"><div><h3>Productive pattern</h3><div id="patterns"></div></div><div><h3>Nearby distinctions</h3><div id="distinctions"></div></div></div></section><section class="section" id="library-section"><h2>Library & evidence</h2><p class="section-lead">Search support and honest provenance boundaries.</p><div class="grid-2" id="library"></div><div class="grid-2" id="evidence" style="margin-top:14px"></div></section><footer class="footer">Germinal prototype · accepted non-live · <span id="accepted-id"></span><br>No live Expressions, main branch, or current release were changed.</footer></main></div><script id="card-data" type="application/json">{safe_json(card)}</script><script id="acceptance-data" type="application/json">{safe_json(acceptance)}</script><script>{JS}</script></body></html>'''

def self_test():
    card={"category":"test","kotoDifficulty":1,"usageSummary":"Test summary","primaryLineId":"l1","japaneseLines":{"l1":{"japanese":"TEST","reading":"test","meaning":"Test meaning","segments":[{"surface":"TEST","reading":"test","kind":"content-or-idiom","contextualMeaning":"test","grammaticalRole":"test","lemma":"test","inflection":None,"selectedVocabularyId":"vocabulary2:"+"a"*32}]}},"intentions":["test"],"useWhen":["test"],"takeCare":["test"],"relationships":[],"forms":[{"kind":"primary","register":"test","lineId":"l1"}],"responses":[],"followUps":[],"dialogue":{"situation":"test","relationship":"test","register":"test","turns":[{"speaker":"A","lineId":"l1"}]},"patterns":{"status":"none-supported","reason":"test"},"distinctions":{"status":"none-supported","reason":"test"},"library":{"searchIntentions":[],"searchMeaning":[],"searchUsage":[],"searchJapanese":[],"searchKana":[]},"sources":[],"provenance":{"editorialStatus":"test"}}
    acceptance={"acceptanceId":"goldacceptance1:"+"a"*32}
    out=render(card,acceptance)
    assert "Full Expression Card" in out and "card-data" in out and "speechSynthesis" in out and "Recognised" in out
    return hashlib.sha256(out.encode()).hexdigest()

def main():
    ap=argparse.ArgumentParser();ap.add_argument("--self-test",action="store_true");ap.add_argument("card",nargs="?");ap.add_argument("acceptance",nargs="?");ap.add_argument("output",nargs="?");x=ap.parse_args()
    if x.self_test:print(json.dumps({"tool":VERSION,"selfTest":"passed","fixtureSha256":self_test()}));return
    if not all((x.card,x.acceptance,x.output)):ap.error("card, acceptance and output are required")
    card=json.loads(pathlib.Path(x.card).read_text(encoding="utf-8"));acc=json.loads(pathlib.Path(x.acceptance).read_text(encoding="utf-8"));out=render(card,acc);pathlib.Path(x.output).write_text(out,encoding="utf-8");print(json.dumps({"tool":VERSION,"bytes":len(out.encode()),"sha256":hashlib.sha256(out.encode()).hexdigest()}))
if __name__=="__main__":main()
